#include <cuda.h>
#include <cuda_runtime.h>
#include <cublas_v2.h>
#include <cublasLt.h>
#include <ATen/cuda/CUDAContext.h>

static cublasLtHandle_t s_lt_handle = nullptr;
static bool s_lt_initialized = false;

static void ensure_lt_handle() {
    if (!s_lt_initialized) {
        cublasLtCreate(&s_lt_handle);
        s_lt_initialized = true;
    }
}

torch::Tensor matmul_with_transposed_b_cuda(torch::Tensor a, torch::Tensor b) {
    TORCH_CHECK(a.is_cuda(), "a must be a CUDA tensor");
    TORCH_CHECK(b.is_cuda(), "b must be a CUDA tensor");
    TORCH_CHECK(a.dtype() == torch::kFloat32, "a must be float32");
    TORCH_CHECK(b.dtype() == torch::kFloat32, "b must be float32");
    TORCH_CHECK(a.dim() == 2, "a must be 2D");
    TORCH_CHECK(b.dim() == 2, "b must be 2D");
    TORCH_CHECK(a.is_contiguous(), "a must be contiguous");
    TORCH_CHECK(b.is_contiguous(), "b must be contiguous");

    int64_t M = a.size(0);
    int64_t K = a.size(1);
    int64_t N = b.size(0);
    TORCH_CHECK(b.size(1) == K, "b.size(1) must equal a.size(1)");

    auto out = torch::empty({M, N}, a.options());

    float alpha = 1.0f;
    float beta = 0.0f;

    // Try cublasLt path
    ensure_lt_handle();

    bool lt_success = false;
    do {
        cublasLtMatmulDesc_t op_desc = nullptr;
        cublasLtMatrixLayout_t layout_a = nullptr, layout_b = nullptr, layout_c = nullptr;
        cublasLtMatmulPreference_t pref = nullptr;

        if (cublasLtMatmulDescCreate(&op_desc, CUBLAS_COMPUTE_32F, CUDA_R_32F) != CUBLAS_STATUS_SUCCESS) break;

        // We compute: out[M,N] = a[M,K] @ b[N,K]^T
        // Using col-major trick: out^T[N,M] = b[N,K] @ a[M,K]^T
        // In cublasLt col-major: C(N,M) = op(A)(N,K) * op(B)(K,M)
        // A_lt = b data, stored row-major [N,K] = col-major [K,N], op=T => [N,K], lda=K
        // B_lt = a data, stored row-major [M,K] = col-major [K,M], op=N => [K,M], ldb=K
        // C_lt = out data, col-major [N,M], ldc=N
