# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <ATen/cuda/CUDAContext.h>

// Tiled TN GEMM: out[M,N] = A[M,K] @ B[N,K]^T
// Each thread block computes a BLOCK_M x BLOCK_N tile of output.
// Each thread computes a TM x TN sub-tile.

#define BLOCK_M 64
#define BLOCK_N 64
#define BLOCK_K 16
#define TM 4
#define TN 4
#define WARP_M (BLOCK_M / TM)   // 16
#define WARP_N (BLOCK_N / TN)   // 16
// threads per block = WARP_M * WARP_N = 256

__global__ void matmul_tn_tiled_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M, int N, int K
) {
    // Block tile origin
    int block_row = blockIdx.y * BLOCK_M;
    int block_col = blockIdx.x * BLOCK_N;

    // Thread index within block
    int tid = threadIdx.x;
    int thread_row = tid / WARP_N;  // 0..15
    int thread_col = tid % WARP_N;  // 0..15

    // Global row/col for this thread's sub-tile
    int row_start = block_row + thread_row * TM;
    int col_start = block_col + thread_col * TN;

    // Shared memory for A and B tiles
    __shared__ float smA[BLOCK_M][BLOCK_K];
    __shared__ float smB[BLOCK_N][BLOCK_K];

    // Accumulator
    float acc[TM][TN];
    #pragma unroll
    for (int i = 0; i < TM; i++)
        #pragma unroll
        for (int j = 0; j < TN; j++)
            acc[i][j] = 0.0f;

    // Number of threads = BLOCK_M * BLOCK_N / (TM * TN) = 256
    // Load A tile: BLOCK_M x BLOCK_K = 64*16 = 1024 elements, 256 threads -> 4 each
    // Load B tile: BLOCK_N x BLOCK_K = 64*16 = 1024 elements, 256 threads -> 4 each

    int num_tiles = (K + BLOCK_K - 1) / BLOCK_K;

    for (int t = 0; t < num_tiles; t++) {
        int k_base = t * BLOCK_K;

        // Load A tile: rows [block_row, block_row+BLOCK_M), cols [k_base, k_base+BLOCK_K)
        // 256 threads load 1024 elements: each thread loads 4
        #pragma unroll
        for (int i = 0; i < 4; i++) {
            int idx = tid + i * 256;
            int r = idx / BLOCK_K;  // 0..63
            int c = idx % BLOCK_K;  // 0..15
            int global_r = block_row + r;
            int global_c = k_base + c;
            smA[r][c] = (global_r < M && global_c < K) ? A[global_r * K + global_c] : 0.0f;
        }

        // Load B tile: rows [block_col, block_col+BLOCK_N), cols [k_base, k_base+BLOCK_K)
        // B[n, k] stored as B[n*K + k]
        #pragma unroll
        for (int i = 0; i < 4; i++) {
            int idx = tid + i * 256;
            int r = idx / BLOCK_K;  // 0..63
            int c = idx % BLOCK_K;  // 0..15
            int global_r = block_col + r;
            int global_c = k_base + c;
            smB[r][c] = (global_r < N && global_c < K) ? B[global_r * K + global_c] : 0.0f;
        }

        __syncthreads();

        // Compute partial products
        #pragma unroll
        for (int k = 0; k < BLOCK_K; k++) {
            float a_reg[TM], b_reg[TN];
            #pragma unroll
            for (int i = 0; i < TM; i++)
                a_reg[i] = smA[thread_row * TM + i][k];
            #pragma unroll
            for (int j = 0; j < TN; j++)
                b_reg[j] = smB[thread_col * TN + j][k];
            #pragma unroll
            for (int i = 0; i < TM; i++)
                #pragma unroll
                for (int j = 0; j < TN; j++)
                    acc[i][j] += a_reg[i] * b_reg[j];
        }

        __syncthreads();
    }

    // Write output
    #pragma unroll
